from collections import defaultdict, deque

def read_ints():
    return list(map(int, input().split()))

# Read input
N, M = read_ints()
E = read_ints()
graph = defaultdict(list)
indegree = [0] * N

# Build the graph and calculate indegree
for _ in range(M):
    T1, T2 = read_ints()
    graph[T2].append(T1)  # Reverse the direction for topological sorting
    indegree[T1] += 1

# Kahn's algorithm for topological sorting
queue = deque()
for i in range(N):
    if indegree[i] == 0:
        queue.append(i)

# Topological order list
topo_order = []

while queue:
    node = queue.popleft()
    topo_order.append(node)
    for neighbor in graph[node]:
        indegree[neighbor] -= 1
        if indegree[neighbor] == 0:
            queue.append(neighbor)

# Calculate the minimal number of coprocessor calls
coprocessor_calls = 0
visited = [False] * N

for node in topo_order:
    if E[node] == 1:  # Task can only be executed on the coprocessor
        if not visited[node]:
            coprocessor_calls += 1
            # Mark all tasks that can be executed along with this task
            queue = deque([node])
            while queue:
                current = queue.popleft()
                if not visited[current]:
                    visited[current] = True
                    for neighbor in graph[current]:
                        if not visited[neighbor]:
                            queue.append(neighbor)

print(coprocessor_calls)
